import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.registerProvider("zq-corp", {
		baseUrl: "http://127.0.0.1:9/v1",
		apiKey: "zq-key",
		api: "openai-completions",
		models: [
			{ id: "zq-large", name: "ZQ Large", reasoning: true, input: ["text", "image"], cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 200000, maxTokens: 32000 },
			{ id: "zq-small", name: "ZQ Small", reasoning: false, input: ["text"], cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 1000, maxTokens: 100 },
