import { Type } from "typebox";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.registerFlag("mood", { type: "string", default: "calm", description: "Mood" });
	pi.registerTool({
		name: "greet",
		label: "Greet",
		description: "Greets someone",
		promptSnippet: "Greet people",
		parameters: Type.Object({ name: Type.String({ description: "Who to greet" }) }),
		async execute(_id, params: { name: string }) {
			return { content: [{ type: "text", text: `Hello, ${params.name}! (${pi.getFlag("mood")})` }], details: { name: params.name } };
		},
	});
	pi.on("tool_result", (event) => (event.toolName === "greet" ? { content: [...event.content, { type: "text", text: "(checked)" }] } : undefined));
	pi.on("before_agent_start", () => ({ message: { customType: "note", content: "Remember the user", display: false } }));
	pi.registerCommand("note", {
		description: "Adds a note",
		handler: async (args) => {
			pi.sendMessage({ customType: "note", content: `note: ${args}`, display: true });
		},
	});
}

export default function (pi) {
	pi.registerTool({
		name: "greet",
		label: "Greet",
		description: "Greets someone",
		parameters: { type: "object", properties: { name: { type: "string" } } },
		async execute(_id, params, _signal, onUpdate, ctx) {
			onUpdate({ content: [{ type: "text", text: "before" }] });
			await ctx.executeTool("read", { path: "hello.txt" });
			onUpdate({ content: [{ type: "text", text: "between" }] });
			await ctx.executeTool("read", { path: "hello.txt" });
			onUpdate({ content: [{ type: "text", text: "after" }] });
			return { content: [{ type: "text", text: `Hello, ${params.name}!` }] };
		},
	});
}

import { Type } from "typebox";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const usage = (output: number) => ({ input: 1, output, cacheRead: 0, cacheWrite: 0, totalTokens: 1 + output, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } });

export default function (pi: ExtensionAPI) {
	pi.registerTool({
		name: "greet",
		label: "Greet",
		description: "Greets someone",
		parameters: Type.Object({ name: Type.String({ description: "Who to greet" }) }),
		async execute(_id, params: { name: string }) {
			return { content: [{ type: "text", text: `Hello, ${params.name}!` }], details: { name: params.name }, structuredContent: { greeting: params.name }, usage: usage(2) };
		},
	});
	pi.on("tool_result", (event) => ({ content: [...event.content, { type: "text", text: JSON.stringify(event) }], structuredContent: { ...event.structuredContent, checked: true }, usage: usage(5) }));
}

