import { calculateCost, createAssistantMessageEventStream, getCurrentSystemPrompt, getCurrentTools } from "@earendil-works/pi-ai";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const delay = () => new Promise((resolve) => setTimeout(resolve, 1));

export default function (pi: ExtensionAPI) {
	pi.registerProvider("echo", {
		name: "Echo",
		baseUrl: "http://127.0.0.1:9/echo",
		apiKey: "echo-key",
		api: "echo-api",
		models: [
			{ id: "echo-1", name: "Echo 1", reasoning: true, input: ["text"], cost: { input: 1, output: 2, cacheRead: 0, cacheWrite: 0 }, contextWindow: 1000, maxTokens: 100 },
			{ id: "echo-fail", name: "Echo Fail", reasoning: false, input: ["text"], cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 1000, maxTokens: 100 },
		],
		streamSimple(model, context, options) {
			const stream = createAssistantMessageEventStream();
			(async () => {
				const output = {
					role: "assistant",
					content: [],
					api: model.api,
					provider: model.provider,
					model: model.id,
					usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } },
					stopReason: "pending",
					timestamp: Date.now(),
				};
				stream.push({ type: "start", partial: output });
				await delay();
				if (model.id === "echo-fail") {
					output.stopReason = "error";
					output.errorMessage = "Echo failed";
					stream.push({ type: "error", reason: "error", error: output });
					stream.end();
					return;
				}
				const last = context.messages[context.messages.length - 1];
				if (last.role === "toolResult") {
					const text = `Read: ${last.content.map((block) => block.text).join("")}`;
					output.content.push({ type: "text", text: "" });
					stream.push({ type: "text_start", contentIndex: 0, partial: output });
					for (const part of [text.slice(0, 5), text.slice(5)]) {
						await delay();
						output.content[0].text += part;
						stream.push({ type: "text_delta", contentIndex: 0, delta: part, partial: output });
					}
					stream.push({ type: "text_end", contentIndex: 0, content: text, partial: output });
					output.stopReason = "stop";
				} else {
					const tools = getCurrentTools(context.messages).map((tool) => tool.name).join(",");
					const thinking = `key=${options?.apiKey} reasoning=${options?.reasoning} tools=${tools} prompt=${getCurrentSystemPrompt(context.messages).includes("pi")}`;
					output.content.push({ type: "thinking", thinking: "" });
					stream.push({ type: "thinking_start", contentIndex: 0, partial: output });
					await delay();
					output.content[0].thinking = thinking;
					stream.push({ type: "thinking_delta", contentIndex: 0, delta: thinking, partial: output });
					stream.push({ type: "thinking_end", contentIndex: 0, content: thinking, partial: output });
					output.content.push({ type: "toolCall", id: "call-1", name: "read", arguments: {} });
					stream.push({ type: "toolcall_start", contentIndex: 1, partial: output });
					await delay();
					const args = JSON.stringify({ path: "hello.txt" });
					stream.push({ type: "toolcall_delta", contentIndex: 1, delta: args, partial: output });
					output.content[1].arguments = JSON.parse(args);
					stream.push({ type: "toolcall_end", contentIndex: 1, toolCall: output.content[1], partial: output });
					output.stopReason = "toolUse";
				}
				output.usage.input = 10;
				output.usage.output = 5;
				output.usage.totalTokens = 15;
				calculateCost(model, output.usage);
				stream.push({ type: "done", reason: output.stopReason, message: output });
				stream.end();
			})();
			return stream;
		},
	});
}

