import { createAssistantMessageEventStream } from "@earendil-works/pi-ai";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	const seen: string[] = [];
	pi.on("after_provider_response", (event) => {
		seen.push(`response ${event.status} ${event.headers["x-echo"]}`);
	});
	pi.on("provider_stream_event", (event) => {
		seen.push(`event ${event.provider} ${event.api} ${event.model} ${(event.data as { type: string }).type}`);
	});
	pi.on("before_provider_request", (event) => ({ ...(event.payload as object), seen: seen.join("; ") }));
	pi.registerProvider("echo", {
		baseUrl: "http://127.0.0.1:9/echo",
		apiKey: "echo-key",
		api: "echo-api",
		models: [{ id: "echo-1", name: "Echo 1", reasoning: false, input: ["text"], cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 1000, maxTokens: 100 }],
		streamSimple(model, context, options) {
			const stream = createAssistantMessageEventStream();
			(async () => {
				await options?.onResponse?.({ status: 200, headers: { "x-echo": "yes" } }, model);
				await options?.onProviderStreamEvent?.({ type: "echo_chunk" }, model);
				const payload = (await options?.onPayload?.({ prompt: "hi" }, model)) ?? { prompt: "hi" };
				const text = JSON.stringify(payload);
				const output = {
					role: "assistant",
					content: [{ type: "text", text: "" }],
					api: model.api,
					provider: model.provider,
					model: model.id,
					usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } },
					stopReason: "stop",
					timestamp: Date.now(),
				};
				stream.push({ type: "start", partial: { ...output, content: [] } });
				stream.push({ type: "text_start", contentIndex: 0, partial: output });
				output.content[0].text = text;
				stream.push({ type: "text_delta", contentIndex: 0, delta: text, partial: output });
				stream.push({ type: "text_end", contentIndex: 0, content: text, partial: output });
				stream.push({ type: "done", reason: "stop", message: output });
				stream.end();
			})();
			return stream;
		},
	});
}

