export default function (pi: ExtensionAPI) {
	pi.registerFlag("mood", { type: "string", default: "calm", description: "Mood" });
	pi.registerTool({
		name: "greet",
		label: "Greet",
		description: "Greets someone",
		promptSnippet: "Greet people",
		parameters: Type.Object({ name: Type.String({ description: "Who to greet" }) }),
		async execute(_id, params: { name: string }) {
			return { content: [{ type: "text", text: `Hello, ${params.name}! (${pi.getFlag("mood")})` }], details: { name: params.name } };
		},
	});
	pi.on("tool_result", (event) => (event.toolName === "greet" ? { content: [...event.content, { type: "text", text: "(checked)" }] } : undefined));
