import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.registerCommand("pick", {
		description: "Pick a fruit",
		handler: async (_args, ctx) => {
			const choice = await ctx.ui.select("Pick a fruit", ["Apple", "Banana", "Cherry"]);
			ctx.ui.notify(choice ? `Picked ${choice}` : "Nothing picked", "info");
		},
	});
	pi.registerCommand("ask", {
		description: "Ask for a name",
		handler: async (_args, ctx) => {
			const name = await ctx.ui.input("Your name?", "name");
			ctx.ui.notify(name ? `Hello, ${name}` : "No name", "info");
		},
	});
	pi.registerCommand("sure", {
		description: "Confirm a deletion",
		handler: async (_args, ctx) => {
			const ok = await ctx.ui.confirm("Delete everything?", "This cannot be undone.");
			ctx.ui.notify(ok ? "Deleted" : "Kept", "info");
		},
	});
	pi.registerCommand("edit", {
		description: "Edit notes",
		handler: async (_args, ctx) => {
			const text = await ctx.ui.editor("Edit notes", "first line\nsecond line");
			ctx.ui.notify(text === undefined ? "Edit cancelled" : `Saved ${text.split("\n").length} lines`, "info");
		},
	});
	pi.registerCommand("note", {
		description: "Show a note",
		handler: async (args) => {
			pi.sendMessage({ customType: "note", content: `**Note:** ${args}`, display: true });
		},
	});
	pi.registerCommand("prefill", {
		description: "Fill the editor",
		handler: async (args, ctx) => {
			ctx.ui.setEditorText(`draft: ${args}`);
			ctx.ui.notify(`Editor: ${ctx.ui.getEditorText()}`, "info");
		},
	});
}

