import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.registerCommand("quiet", {
		description: "Stop listening",
		handler: async (_args, ctx) => {
			stop?.();
			ctx.ui.notify("Stopped listening", "info");
		},
	});
	let stop: (() => void) | undefined;
	pi.on("session_start", (_event, ctx) => {
		let seen = 0;
		stop = ctx.ui.onTerminalInput((data) => {
			seen++;
			if (data === "x") return { consume: true };
			if (data === "a") return { data: "A" };
			if (data === "\x07") {
				ctx.ui.notify(`Saw ${seen} keys, editor: ${ctx.ui.getEditorText()}`, "info");
				return { consume: true };
			}
			return undefined;
		});
	});
}

