import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
export default function (pi: ExtensionAPI) {
	pi.registerCommand("stack", {
		description: "Three overlays",
		handler: async (_args, ctx) => {
			const closed: string[] = [];
			const show = (n: number) =>
				ctx.ui
					.custom<string>(
						(_tui, _theme, _kb, done) => ({
							render: (width: number) => [`+${"-".repeat(width - 2)}+`, `| Overlay ${n}`.padEnd(width - 1) + "|", `+${"-".repeat(width - 2)}+`],
							handleInput: (data: string) => {
								if (data === "\r") done(`Overlay ${n}`);
							},
							invalidate: () => {},
						}),
						{ overlay: true, overlayOptions: { anchor: "top-left", row: 8 + n * 2, col: n * 4, width: 30 } },
					)
					.then((value) => closed.push(value));
			await Promise.all([show(1), show(2), show(3)]);
			ctx.ui.notify(`Closed in order: ${closed.join(", ")}`, "info");
		},
	});
}

