import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	let refusedNew = false;
	const log = (event: { type: string }, ctx: { ui: { notify(message: string): void } }) =>
		ctx.ui.notify(JSON.stringify(event, (key, value) => (key === "entryId" ? typeof value : value)));
	pi.on("session_start", log);
	pi.on("session_shutdown", log);
	pi.on("session_before_switch", (event, ctx) => {
		log(event, ctx);
		if (event.reason === "new" && !refusedNew) {
			refusedNew = true;
			return { cancel: true };
		}
	});
	pi.on("session_before_fork", (event, ctx) => {
		log(event, ctx);
		if (event.position === "at") return { cancel: true };
	});
}

