		const { preparation } = event;
		ctx.ui.notify(
			`${event.type} ${event.reason} ${event.willRetry} ${event.customInstructions} ${preparation.messagesToSummarize.length} ${preparation.isSplitTurn} ${preparation.settings.keepRecentTokens}`,
		);
		if (event.customInstructions === "cancel") return { cancel: true };
		return {
			compaction: {
				summary: "From the extension",
				firstKeptEntryId: preparation.firstKeptEntryId,
				tokensBefore: preparation.tokensBefore,
				details: { custom: true },
			},
		};
	});
	pi.on("session_compact", (event, ctx) =>
		ctx.ui.notify(`${event.type} ${event.reason} ${event.fromExtension} ${event.compactionEntry.summary} ${event.compactionEntry.fromHook}`),
	);
	pi.on("session_compact_failed", (event, ctx) => ctx.ui.notify(JSON.stringify(event)));
}

