import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.on("user_bash", (event) => {
		if (event.command === "fake") {
			return { result: { output: `faked ${event.excludeFromContext}`, exitCode: 0, cancelled: false, truncated: false } };
		}
		if (event.command.startsWith("remote ")) {
			return {
				operations: {
					exec: async (command: string, cwd: string, options: { onData(data: Buffer): void }) => {
						options.onData(Buffer.from(`ran ${command}\n`));
						options.onData(Buffer.from(`in ${cwd}\n`));
						return { exitCode: 7 };
					},
				},
			};
		}
		if (event.command === "bad") throw new Error("no bash for you");
		if (event.command === "invalid") return {} as never;
	});
}

