import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	let turns = 0;
	pi.on("turn_end", (event) => {
		turns++;
		if (turns > 1) return;
		const { context } = event;
		const note = [
			`turn ${event.turnIndex}`,
			event.outcome,
			typeof event.messageEntryId,
			event.toolResultEntryIds.length,
			event.entries.length,
			event.continue,
			context.canContinue,
			context.contextMessages.length,
			context.llmMessages.map((message) => message.role).join(","),
			context.pendingMessages.length,
		].join(" ");
		return {
			entries: [...event.entries, { type: "custom_message", customType: "nudge", content: note, display: false }],
			continue: true,
		};
	});
	pi.on("agent_before_settle", (event) => ({
		entries: [
			...event.entries,
			{ type: "custom", customType: "settled", data: { outcome: event.outcome, canContinue: event.context.canContinue } },
		],
	}));
}

