import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	const roles = (messages: { role: string }[]) => messages.map((message) => message.role).join(",");
	pi.on("context", (event, ctx) => ctx.ui.notify(`context ${roles(event.messages)}`));
	pi.on("context_with_system", (event, ctx) => ctx.ui.notify(`context_with_system ${roles(event.messages)}`));
	pi.on("before_provider_headers", (event, ctx) => {
		event.headers["x-trace"] = "abc";
		ctx.ui.notify(`headers ${Object.keys(event.headers).sort().join(",")}`);
	});
	pi.on("after_provider_response", (event, ctx) => ctx.ui.notify(`response ${event.status} ${event.headers["request-id"]}`));
	const streamed: string[] = [];
	pi.on("provider_stream_event", (event) => {
		streamed.push(`${event.provider} ${event.api} ${event.model} ${(event.data as { type: string }).type}`);
	});
	pi.on("agent_end", (_event, ctx) => ctx.ui.notify(`streamed ${streamed.join("; ")}`));
	pi.on("ui_prompt_start", (event, ctx) => ctx.ui.notify(JSON.stringify(event)));
	pi.on("ui_prompt_end", (event, ctx) => ctx.ui.notify(JSON.stringify(event)));
	pi.registerCommand("ask", {
		description: "Asks",
		handler: async (_args, ctx) => {
			const choice = await ctx.ui.select("Pick one", ["a", "b"], { timeout: 50 });
			ctx.ui.notify(`picked ${choice}`);
		},
	});
}

