import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.on("tool_call", (event) => {
		if (event.toolName === "read") event.input.path = "other.txt";
	});
	pi.on("message_end", (event) => {
		const { message } = event;
		if (message.role !== "assistant") return;
		if (message.stopReason === "stop") return { message: { ...message, content: null } };
		const content = message.content.map((block) => (block.type === "text" ? { ...block, text: `${block.text} (edited)` } : block));
		return { message: { ...message, content } };
	});
	pi.on("message_end", (event) => {
		if (event.message.role === "user") return { message: { ...event.message, role: "assistant" } };
	});
}

