import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.on("tool_call", (event) => {
		if (event.input.path === "other.txt") event.input.offset = 2;
	});
	pi.on("tool_result", (event) => ({
		content: [...event.content, { type: "text", text: JSON.stringify(event.input) }],
	}));
	pi.on("message_end", (event) => {
		const { message } = event;
		if (message.role !== "assistant" || !Array.isArray(message.content)) return;
		const content = message.content.map((block) => (block.type === "text" ? { ...block, text: `${block.text} (twice)` } : block));
		return { message: { ...message, content } };
	});
}

