import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	const say = (ctx: { ui: { notify(message: string, type?: "warning"): void } }, message: string) =>
		ctx.ui.notify(message, "warning");
	pi.on("session_start", (event, ctx) => say(ctx, `start ${event.reason}`));
	pi.on("session_shutdown", (event, ctx) => say(ctx, `shutdown ${event.reason}`));
	pi.on("session_before_switch", (event) => {
		if (event.targetSessionFile?.endsWith("blocked.jsonl")) return { cancel: true };
	});
	pi.registerCommand("act", {
		description: "Changes the session",
		handler: async (args, ctx) => {
			const [what, value] = args.split(" ");
			const manager = ctx.sessionManager;
			if (what === "new") {
				const parent = manager.getSessionFile();
				const result = await ctx.newSession({
					parentSession: parent,
					withSession: async (next) => {
						say(next, `with new ${next.sessionManager.getHeader()?.parentSession === parent}`);
						await next.sendMessage({ customType: "note", content: "seeded", display: true });
					},
				});
				say(ctx, `new ${result.cancelled}`);
			} else if (what === "fork") {
				const first = manager.getEntries().find((entry) => entry.type === "message" && entry.message.role === "user");
				const result = await ctx.fork(first.id, {
					withSession: async (next) => say(next, `with fork ${next.sessionManager.getEntries().length}`),
				});
				say(ctx, `fork ${result.cancelled}`);
			} else if (what === "clone") {
				const result = await ctx.fork(manager.getLeafId(), {
					position: "at",
					withSession: async (next) => say(next, `with clone ${next.sessionManager.getEntries().length}`),
				});
				say(ctx, `clone ${result.cancelled}`);
			} else if (what === "tree") {
				const first = manager.getEntries().find((entry) => entry.type === "message" && entry.message.role === "assistant");
				const result = await ctx.navigateTree(first.id, { label: "here" });
				say(ctx, `tree ${result.cancelled} ${manager.getLeafId() === first.id} ${manager.getLabel(first.id)}`);
			} else if (what === "switch") {
				const result = await ctx.switchSession(value, {
					withSession: async (next) => say(next, `with switch ${next.sessionManager.getSessionFile() === value}`),
				});
				say(ctx, `switch ${result.cancelled}`);
			} else if (what === "reload") {
				await ctx.reload();
			} else if (what === "theme") {
				const result = ctx.ui.setTheme(value);
				say(ctx, `theme ${result.success} ${result.error}`);
			}
		},
	});
}

