import { readFileSync } from "node:fs";
import { join } from "node:path";
import { type ExtensionAPI, getAgentDir, Theme } from "@earendil-works/pi-coding-agent";

const FG = "accent border borderAccent borderMuted success error warning muted dim text thinkingText userMessageText customMessageText customMessageLabel toolTitle toolOutput mdHeading mdLink mdLinkUrl mdCode mdCodeBlock mdCodeBlockBorder mdQuote mdQuoteBorder mdHr mdListBullet toolDiffAdded toolDiffRemoved toolDiffContext syntaxComment syntaxKeyword syntaxFunction syntaxVariable syntaxString syntaxNumber syntaxType syntaxOperator syntaxPunctuation thinkingOff thinkingMinimal thinkingLow thinkingMedium thinkingHigh thinkingXhigh bashMode";
const BG = "selectedBg userMessageBg customMessageBg toolPendingBg toolSuccessBg toolErrorBg";
const colors = (tokens: string, value: string) => Object.fromEntries(tokens.split(" ").map((token) => [token, value]));

export default function (pi: ExtensionAPI) {
	pi.registerCommand("paint", {
		description: "Sets a Theme object",
		handler: async (args, ctx) => {
			const say = (message: string) => ctx.ui.notify(message, "warning");
			let theme;
			if (args === "light") {
				theme = ctx.ui.getTheme("light");
				say(`missing ${ctx.ui.getTheme("nope")}`);
			} else {
				theme = new Theme({ ...colors(FG, "#5f87af"), accent: 39, muted: "" }, colors(BG, "okhsl(200 50% 20%)"), "256color", { name: "custom" });
			}
			say(JSON.stringify([theme.name, theme.fg("accent", "a"), theme.fg("muted", "m"), theme.bg("selectedBg", "s"), theme.fg("scrollbarThumb", "t")]));
			say(`set ${JSON.stringify(ctx.ui.setTheme(theme))}`);
			say(`saved ${args} ${JSON.parse(readFileSync(join(getAgentDir(), "settings.json"), "utf8")).theme}`);
		},
	});
}

